export const evolutionTimelineData=[{era:"Earliest & Traditional",period:"Pre-1888",year:1850,title:"Traditional Kushti Gada & Vallam Kali Paddles",subtitle:"Sacred Symbols of Strength & Community Mastery",category:"Traditional",materials:"Solid Brass, Carved Teakwood, Silver Foil",description:"Before Western organized sports trophies took root in India, traditional Indian sports honored champions with sacred physical symbols. In Indian wrestling (Kushti / Pehlwani), champions like Rustam-e-Hind were awarded the 'Gada'—a heavy brass or silver-plated mace symbolizing Lord Hanuman's strength. In Kerala's snake boat races (Vallam Kali), winning rowers were presented with hand-carved teakwood paddles decorated with brass work.",designFeature:"Sacred mace shape, religious iconography, natural teakwood carving.",icon:"🔱"},{era:"Colonial Era",period:"1888",year:1888,title:"Durand Cup: Asia's Oldest Football Trophy",subtitle:"British Administrative Sterling Silver Crafting",category:"Football",materials:"Sterling Silver, Polished Wooden Base",description:"Sir Mortimer Durand, Foreign Secretary of British India, instituted the Durand Cup in Shimla in 1888. The original trophy was a majestic sterling silver three-handled urn manufactured in London. Over time, two additional replica trophies (the Shimla Trophy and President's Cup) were added, making the winner's presentation a triple-trophy ritual.",designFeature:"Classic British 3-handled silver urn with intricate floral scrollwork.",icon:"⚽"},{era:"Colonial Era",period:"1893",year:1893,title:"IFA Shield: The Majestic Silver Crest of Bengal",subtitle:"Heavy Embossed Silver Plaque from London",category:"Football",materials:"High-grade Sterling Silver, Velvet Mount, Oak Board",description:"The Indian Football Association (IFA) in Kolkata instituted the IFA Shield in 1893. Imported directly from silversmiths in England, the shield features an elaborate relief depicting football players in action surrounded by Victorian oak leaf motifs. In 1911, Mohun Bagan created history by becoming the first native Indian club to defeat East Yorkshire Regiment to lift the shield.",designFeature:"Heavy embossed silver shield mounted on dark polished oak board.",icon:"🛡️"},{era:"Colonial Era",period:"1934",year:1934,title:"Ranji Trophy: The Royal Patiala Urn",subtitle:"Greco-Roman Silver Masterpiece",description:"Donated by Maharaja Bhupinder Singh of Patiala in 1934 to honor Jam Saheb Ranjitsinhji of Nawanagar ('Ranji'). The Ranji Trophy is a spectacular 2-foot-tall sterling silver Greco-Roman urn featuring ornate scrolled handles, a domed lid topped with a classic batsman figure, and an engraved wooden pedestal listing historic winner states.",designFeature:"Greco-Roman dual-handle urn with top-mounted cricketer figurine.",icon:"🏏"},{era:"Colonial Era",period:"1941",year:1941,title:"Santosh Trophy: Maharaja of Santosh's Gift",subtitle:"Ornate Silver Relief Work",category:"Football",materials:"Sterling Silver, Mahogany Base",description:"Instituted by the Indian Football Association in 1941 in memory of Sir Manmatha Nath Roy Chowdhury, Maharaja of Santosh. The trophy was crafted in silver with intricate hand-chased relief work showing football players, lions, and royal coats of arms.",designFeature:"Ornate silver punch bowl and chalice with lions and royal motifs.",icon:"🏆"},{era:"Post-Independence Era",period:"1952",year:1952,title:"Nehru Trophy: Silver Snake Boat Replica",subtitle:"Jawaharlal Nehru's Personal Gift to Kerala",category:"Traditional Sports",materials:"Pure Silver, Teakwood Pedestal",description:"After witnessing the electrifying 1952 snake boat race at Punnamada Lake, Alappuzha, Prime Minister Jawaharlal Nehru personally commissioned a pure silver replica of a Chundan Vallam (Snake Boat) sitting atop a wooden base. The trophy features Nehru's engraved signature and a miniature silver boat with rowers.",designFeature:"Silver miniature snake boat with rowers mounted on polished wood.",icon:"🚣‍♂️"},{era:"Post-Independence Era",period:"1961",year:1961,title:"Arjuna Award: The Indigenous Bronze Statuette",subtitle:"Symbol of Archer Focus & Determination",category:"Multi-Sport",materials:"Cast Bronze, Marble Pedestal",description:"The Government of India established the Arjuna Award in 1961. Breaking away from British urns and shields, the award introduced a distinctively Indian aesthetic: a statuette of Arjuna from the Mahabharata taking aim with his bow, symbolizing supreme focus, courage, and sportsmanship.",designFeature:"Cast bronze statuette of warrior Arjuna with bow and arrow.",icon:"🏹"},{era:"Post-Independence Era",period:"1985",year:1985,title:"Dronacharya Award: Honoring the Guru",subtitle:"Guru-Shishya Tradition in Sports",category:"Multi-Sport",materials:"Cast Bronze, Wooden Base",description:"Instituted in 1985 to honor outstanding sports coaches. The statuette depicts Guru Dronacharya handing an arrow to his star pupil Arjuna, capturing the ancient Indian Guru-Shishya Parampara (teacher-disciple tradition) in modern sports.",designFeature:"Bronze statuette depicting Guru Dronacharya handing arrow to Arjuna.",icon:"📜"},{era:"Modern Era",period:"1991 / 2021",year:1991,title:"Major Dhyan Chand Khel Ratna Award",subtitle:"India's Highest Sporting Honor Renamed for the Wizard",category:"Multi-Sport",materials:"Gold Medal Medallion, Silk Scroll, Commemorative Plaque",description:"Instituted in 1991–92 as the Rajiv Gandhi Khel Ratna, India's highest sporting award was officially renamed in August 2021 as the 'Major Dhyan Chand Khel Ratna Award' to honor field hockey wizard Dhyan Chand. The award includes a heavy gold medallion, a formal citation scroll, and a cash reward.",designFeature:"Embossed national emblem gold medallion with tri-color ribbon.",icon:"🥇"},{era:"Modern Era",period:"2008",year:2008,title:"IPL Trophy: 24K Gold-Gilded & Sanskrit Motto",subtitle:"'Yatra Pratibha Avsara Prapnoti'",category:"Cricket",materials:"24K Gold-Plated Brass, Diamond Accents, Map Outline",description:"Launched in 2008 with the Indian Premier League, the IPL Trophy represents modern sports glamour. Designed by Orra Jewelry, the trophy features a map of India in gold, studded with diamonds, and is inscribed in Devanagari script with the Sanskrit motto: 'Yatra Pratibha Avsara Prapnoti' ('Where talent meets opportunity').",designFeature:"Gold-gilded map of India with Sanskrit Devanagari inscription.",icon:"💎"},{era:"Modern Era",period:"2014",year:2014,title:"ISL Trophy: Modern Geometric Ribbon Concept",subtitle:"Sleek Anodized Chrome & Brass",category:"Football",materials:"Anodized Chrome, Polished Brass, Matte Black Base",description:"The Indian Super League (ISL) trophy introduced in 2014 was designed by Frazer and Haws in London. The trophy features a dynamic geometric ribbon structure that spirals upward, representing velocity, modern athleticism, and the unification of Indian football.",designFeature:"Spiraling chrome ribbon loop encircling an inner golden football.",icon:"⚽"},{era:"Modern Era",period:"2014",year:2014,title:"Pro Kabaddi League (PKL) Trophy",subtitle:"Capturing the Dynamic Kabaddi Raid Stance",category:"Traditional Sports",materials:"Polished Chrome, Solid Brass, Heavy Marble Pedestal",description:"The Pro Kabaddi League trophy combines traditional Indian sport heritage with high-tech modern aesthetics. It features a stylized chrome statuette of a Kabaddi raider in mid-flight stance, capturing the power, agility, and ancient roots of Kabaddi.",designFeature:"Stylized chrome raider in mid-flight action stance.",icon:"🤼‍♂️"}];export const designMaterialsComparison=[{era:"Colonial Era (1888 - 1946)",primaryMaterials:"Heavy Sterling Silver, Oak Boards, Mahogany Pedestals",designStyle:"Victorian & Greco-Roman Urns, Dual-handle Chalices, Embossed Crests",symbolism:"British Imperial Majesty, Crown patronage, Victorian floral motifs",keyExamples:"Durand Cup, Ranji Trophy Urn, IFA Shield, Rovers Cup"},{era:"Post-Independence (1947 - 1989)",primaryMaterials:"Cast Bronze, Pure Silver Replicas, Marble Blocks",designStyle:"Indigenous Sculptural Statuettes, Epic Iconography (Mahabharata)",symbolism:"Indian national identity, Mahabharata archers (Arjuna), Guru-Shishya tradition",keyExamples:"Arjuna Award Statuette, Dronacharya Award, Nehru Boat Race Silver Snake"},{era:"Modern & Franchise Era (1990 - Present)",primaryMaterials:"24K Gold Plating, Diamond Accents, Anodized Chrome, Carbon Accents",designStyle:"Futuristic Geometric Loops, Sanskrit Inscriptions, Dynamic Action Stances",symbolism:"Global broadcast glamour, corporate excellence, Sanskrit mottos ('Talent meets Opportunity')",keyExamples:"IPL Gold Trophy, ISL Chrome Ribbon, PKL Raider Statuette, Khel Ratna Gold Medallion"}];export const namingChangesArchive=[{originalName:"Rajiv Gandhi Khel Ratna Award (1991)",newName:"Major Dhyan Chand Khel Ratna Award (2021)",reason:"Renamed by the Government of India in August 2021 to honor Hockey Legend Major Dhyan Chand following public acclaim after India's Olympic hockey resurgence in Tokyo."},{originalName:"National Limited Overs Tournament (1993)",newName:"Vijay Hazare Trophy (2002)",reason:"Renamed in 2002–03 by the BCCI to honor Vijay Hazare, who captained India to its historic first Test win in 1952."},{originalName:"Prime Minister's Trophy (1952)",newName:"Nehru Trophy Boat Race (1954)",reason:"Renamed after Jawaharlal Nehru donated his signed silver snake boat trophy to Alappuzha following his 1952 visit."},{originalName:"Women's Inter-State Cricket Cup",newName:"Rani of Jhansi Trophy (1974)",reason:"Instituted by the Women's Cricket Association of India to symbolize female courage and national pride."}];export const quizQuestions=[{id:1,question:"What Sanskrit motto is inscribed in Devanagari on the 24K gold-plated IPL Trophy?",options:["Satyameva Jayate","Yatra Pratibha Avsara Prapnoti","Khelam Shrestham","Vasudhaiva Kutumbakam"],answer:1,explanation:"'Yatra Pratibha Avsara Prapnoti' translates to 'Where talent meets opportunity'."},{id:2,question:"What material and figure is featured on India's prestigious Arjuna Award introduced in 1961?",options:["Gold Chalice","Cast Bronze Statuette of Archer Arjuna","Silver Shield with Lions","Teakwood Paddle"],answer:1,explanation:"The Arjuna Award features a cast bronze statuette of Arjuna taking aim with his bow."},{id:3,question:"In August 2021, India's highest sporting award (formerly Rajiv Gandhi Khel Ratna) was renamed in honor of which sports legend?",options:["Milkha Singh","Major Dhyan Chand","Sachin Tendulkar","K.D. Jadhav"],answer:1,explanation:"It was officially renamed the Major Dhyan Chand Khel Ratna Award to honor hockey icon Dhyan Chand."},{id:4,question:"What physical form does the Ranji Trophy, donated by the Maharaja of Patiala in 1934, take?",options:["Greco-Roman Silver Urn","Bronze Shield","Gold Medal","Crystal Crown"],answer:0,explanation:"The Ranji Trophy is a 2-foot-tall sterling silver Greco-Roman urn with elaborate handles and a lid topped with a batsman."},{id:5,question:"Which traditional water sport award features a pure silver miniature boat signed by India's first Prime Minister?",options:["Durand Cup","Nehru Trophy Boat Race","Trades Cup","Santosh Trophy"],answer:1,explanation:"Jawaharlal Nehru personally gifted a signed silver snake boat replica in 1952 for the Nehru Trophy Boat Race in Alappuzha."}];